import 'package:flutter/foundation.dart';\nimport 'package:socket_io_client/socket_io_client.dart' as IO;\n\nclass DeviceStateProvider extends ChangeNotifier {\n  IO.Socket? socket;\n  \n  bool _isOn = false;\n  double _brightness = 1.0;\n  int _r = 255, _g = 255, _b = 255;\n  \n  bool get isOn => _isOn;\n  double get brightness => _brightness;\n  List<int> get color => [_r, _g, _b];\n\n  void connectSocket(String deviceId) {\n    socket = IO.io('http://YOUR_BACKEND_IP:3000', <String, dynamic>{\n      'transports': ['websocket'],\n      'query': {'deviceId': deviceId}\n    });\n    \n    socket?.onConnect((_) {\n      if (kDebugMode) print('Connected to Cloud Relay');\n    });\n\n    // Used if we have bidirectional sync\n    socket?.on('sync_color', (data) {\n      // Handle remote loopback if needed\n    });\n  }\n\n  // Traditional Control (could hit matter directly, or go to cloud)\n  void setPower(bool state) {\n    _isOn = state;\n    notifyListeners();\n    // TODO: Send to matter or server\n  }\n\n  void updateColor(int r, int g, int b) {\n    _r = r;\n    _g = g;\n    _b = b;\n    notifyListeners();\n  }\n\n  // MUSIC SYNC - high frequency, low footprint\n  void sendMusicSyncFrame(String deviceId, int h, int s, int v) {\n    socket?.emit('music_sync_frame', {\n      'deviceId': deviceId,\n      'h': h,\n      's': s,\n      'v': v\n    });\n  }\n\n  @override\n  void dispose() {\n    socket?.disconnect();\n    super.dispose();\n  }\n}\n
